"""Retrieval with query decomposition (temporal sub-questions) and RRF fusion.

Two decomposition sources:
  --mode steps : the organizers' official step decomposition (steps_*.jsonl,
                 sub-track 1b). Evaluating it at the 1a level gives an *upper
                 bound* on what a perfect temporal decomposition could buy.
  --mode llm   : sub-questions generated by the local instruct model
                 (--decomp-json from decompose_temporal.py) — the realistic,
                 test-time-available variant.

Fusion: RRF over the per-sub-question rankings, optionally plus the original
query ranking with weight --w0.

Usage:
  python run_decomposed_retrieval.py --domain bitcoin --split dev --mode steps \
      --out runs/decomp_steps_bitcoin_dev.trec --meta results/...json
"""
import argparse
import json
import os
import re
import sys

import numpy as np

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from lib_reteco import load_corpus, write_trec_run  # noqa: E402

ROOT = r"D:\RETECO"
INSTRUCTION = "Represent this sentence for searching relevant passages: "


def clean(t):
    t = re.sub(r"<[^>]+>", " ", t or "")
    return re.sub(r"\s+", " ", t).strip()


def load_steps(domain, split):
    path = os.path.join(ROOT, "data", "track1_tempo", domain, f"steps_{split}.jsonl")
    out = {}
    if os.path.isfile(path):
        with open(path, encoding="utf-8") as f:
            for line in f:
                r = json.loads(line)
                out[r["id"]] = [clean(s.get("step_instruction") or s.get("step", ""))
                                for s in r.get("steps", [])]
    return out


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--domain", required=True)
    ap.add_argument("--split", required=True)
    ap.add_argument("--mode", required=True, choices=["steps", "llm"])
    ap.add_argument("--decomp-json", default=None)
    ap.add_argument("--w0", type=float, default=1.0, help="weight of the original query")
    ap.add_argument("--c", type=float, default=60.0)
    ap.add_argument("--topk", type=int, default=1000)
    ap.add_argument("--out", required=True)
    ap.add_argument("--meta", required=True)
    args = ap.parse_args()

    import torch
    from transformers import AutoModel, AutoTokenizer

    ids, _ = load_corpus(os.path.join(ROOT, "data", "track1_tempo", args.domain))
    emb = np.load(os.path.join(ROOT, "emb",
                               f"doc_emb_bge-base-en-v1.5_{len(ids)}.npy"))
    qmap = {}
    with open(os.path.join(ROOT, "data", "track1_tempo", args.domain,
                           f"examples_{args.split}.jsonl"), encoding="utf-8") as f:
        for line in f:
            r = json.loads(line)
            qmap[r["id"]] = clean(r["query"])

    if args.mode == "steps":
        decomp = load_steps(args.domain, args.split)
    else:
        decomp = json.load(open(args.decomp_json, encoding="utf-8"))

    tok = AutoTokenizer.from_pretrained(os.path.join(ROOT, "models", "bge-base-en-v1.5"))
    model = AutoModel.from_pretrained(os.path.join(ROOT, "models", "bge-base-en-v1.5"),
                                      torch_dtype=torch.float16).eval().cuda()
    doc_t = torch.from_numpy(emb).cuda()

    def encode(texts):
        out = []
        with torch.inference_mode():
            for i in range(0, len(texts), 16):
                enc = tok([INSTRUCTION + t for t in texts[i:i + 16]], padding=True,
                          truncation=True, max_length=512,
                          return_tensors="pt").to("cuda")
                h = model(**enc).last_hidden_state[:, 0].float()
                out.append(torch.nn.functional.normalize(h, dim=-1).cpu().numpy())
        return np.concatenate(out, 0)

    qids = list(qmap)
    all_texts, spans = [], []
    for qid in qids:
        subs = [s for s in decomp.get(qid, []) if s]
        texts = [qmap[qid]] + subs
        spans.append((len(all_texts), len(all_texts) + len(texts)))
        all_texts.extend(texts)
    qemb = encode(all_texts)

    ranked, stats = {}, {"queries": 0, "subqueries": 0, "avg_sub": 0.0}
    for k, qid in enumerate(qids):
        s, e = spans[k]
        score = {}
        for j in range(s, e):
            w = args.w0 if j == s else 1.0
            sims = doc_t @ torch.from_numpy(qemb[j]).cuda()
            vals, idx = torch.topk(sims, min(args.topk, sims.shape[0]))
            for r, (vi, ii) in enumerate(zip(vals.tolist(), idx.tolist())):
                score[ids[ii]] = score.get(ids[ii], 0.0) + w / (args.c + r + 1)
        ranked[qid] = sorted(score.items(), key=lambda x: (-x[1], x[0]))
        stats["queries"] += 1
        stats["subqueries"] += (e - s - 1)
    stats["avg_sub"] = stats["subqueries"] / max(1, stats["queries"])

    write_trec_run(args.out, ranked, tag=f"decomp-{args.mode}")
    meta = {"domain": args.domain, "split": args.split, "mode": args.mode,
            "w0": args.w0, "c": args.c, "topk": args.topk, "stats": stats,
            "run_file": os.path.abspath(args.out)}
    with open(args.meta, "w", encoding="utf-8") as f:
        json.dump(meta, f, indent=2)
    print(json.dumps(stats))


if __name__ == "__main__":
    main()
